import{_ as a,o as s,c as t,a2 as e}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"速率限制","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/advanced/ratelimit.md","filePath":"zh-CN/advanced/ratelimit.md","lastUpdated":1784903584000}'),n={name:"zh-CN/advanced/ratelimit.md"};function l(o,i,r,h,d,p){return s(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="速率限制" tabindex="-1">速率限制 <a class="header-anchor" href="#速率限制" aria-label="Permalink to &quot;速率限制&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>swag2mcp 内置了速率限制器，防止 LLM 过于频繁地调用同一 API 端点。这可以防止意外的重复调用，并尊重 API 的速率限制。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>每个端点都有一个冷却期。如果 LLM 在冷却期内尝试再次调用同一端点，该调用将被拒绝并返回结构化错误。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → 执行</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → 被拒绝，返回 rate_limit 错误</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → 执行（冷却期已过）</span></span></code></pre></div><h3 id="默认行为" tabindex="-1">默认行为 <a class="header-anchor" href="#默认行为" aria-label="Permalink to &quot;默认行为&quot;">​</a></h3><ul><li><strong>冷却时间：</strong> 每个端点 10 秒</li><li><strong>范围：</strong> 按端点 — 调用端点 A 不影响端点 B</li><li><strong>错误响应：</strong> LLM 收到代码为 <code>rate_limit</code> 的 <code>LLMError</code>，并附带指示等待时间的消息</li><li><strong>重置：</strong> 该端点 10 秒无活动后</li></ul><h3 id="错误格式" tabindex="-1">错误格式 <a class="header-anchor" href="#错误格式" aria-label="Permalink to &quot;错误格式&quot;">​</a></h3><p>当触发速率限制时，LLM 会收到：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate limit exceeded for endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: try again in 8 seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wait for the cooldown period to expire, then try invoking the endpoint again. Use the search tool to find other endpoints you can call in the meantime.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>LLM 可以使用此信息等待并重试，或切换到不同的端点。</p><h3 id="为什么存在" tabindex="-1">为什么存在 <a class="header-anchor" href="#为什么存在" aria-label="Permalink to &quot;为什么存在&quot;">​</a></h3><ul><li><strong>防止意外重复调用</strong> — LLM 可能在短时间内多次调用同一端点</li><li><strong>防止 API 速率限制</strong> — 许多 API 有自己的速率限制，触发它们会导致错误</li><li><strong>节省资源</strong> — 减少不必要的网络流量</li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>你可以禁用速率限制器或更改冷却间隔：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 完全禁用速率限制器</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自定义冷却间隔</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>类型：</strong> <code>bool</code></li><li><strong>默认值：</strong> <code>false</code></li><li><strong>效果：</strong> 当为 <code>true</code> 时，按端点的速率限制器被禁用。LLM 可以重复调用同一端点而无需等待。</li><li><strong>何时启用：</strong> 测试、调试，或需要快速连续多次调用同一端点时。</li><li><strong>何时保持禁用（推荐）：</strong> 生产环境。速率限制器防止意外滥用。</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>类型：</strong> 持续时间（Go 格式：<code>10s</code>、<code>30s</code>、<code>1m</code>）</li><li><strong>默认值：</strong> <code>10s</code></li><li><strong>效果：</strong> 设置对同一端点的两次调用之间的冷却期。</li><li><strong>何时增加：</strong> 具有严格速率限制的 API（例如每分钟 10 次请求）。</li><li><strong>何时减少：</strong> 你可以控制负载的内部 API。</li><li><strong>示例：</strong> <code>5s</code>、<code>30s</code>、<code>1m</code>、<code>2m</code></li></ul><h2 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h2><ul><li><strong>按端点跟踪</strong> — 每个端点独立跟踪。调用一个端点不影响其他端点。</li><li><strong>错误返回给 LLM</strong> — 冷却期内的第二次调用被拒绝，返回 <code>rate_limit</code> 错误。LLM 收到冷却持续时间，可以在等待后重试。</li><li><strong>无需清理</strong> — 速率限制器自动跟踪端点，无需维护。</li></ul>`,23)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
